		{"delete byte in the path", "/api/x\x7f", "U+007F"},
		{"space in the path", "/api/orders next", "U+0020"},
		{"space in a parameter name", "/p?a b=1", "U+0020"},
		{"tab in a parameter name", "/p?a\tb=1", "U+0009"},
